//
// What to do with a clipboard change, decided from plain values so it can be tested without a
// pasteboard. Behaviour follows Clop 3.5: skip our own writes and the nspasteboard.org transient,
// concealed and auto-generated markers, skip copies made in ignored apps, optimise copied image
// data, and copied files only when their kind's clipboard setting is on and they are not marked
// as already optimised. A copied web address of such a file is offered for download, and fetched
// only on the offer's click (or on its own when the person chose that). Clop's watcher leaves
// addresses alone; only its Optimise Clipboard hotkey and a drop download one.

import AppKit
import EsclopCore
import EsclopIPC
import EsclopOptimisers
import Foundation
import UniformTypeIdentifiers

/// One copy, read once on the clipboard queue: the change count it has (the clipboard is still
/// that copy while the count stays), the app in front and the pasteboard types. Every later
/// decision about the copy uses these values, never a second look.
public struct ClipboardCopy: Equatable, Sendable {
    public var changeCount: Int
    public var app: String?
    public var types: Set<String>

    public init(changeCount: Int, app: String? = nil, types: Set<String> = []) {
        self.changeCount = changeCount
        self.app = app
        self.types = types
    }
}

public enum ClipboardAction: Equatable, Sendable {
    case ignore(Reason)
    case optimiseImage(Data, UTType, ClipboardCopy)
    /// The files to optimise, and every file copied, in order: the results go back in their places.
    case optimiseFiles([URL], copied: [URL], ClipboardCopy)
    /// A copied web address of a media file, to download and then optimise as a copied file.
    case optimiseAddress(URL, ClipboardCopy)
    /// A copied web address of a media file, to offer for download; nothing is fetched yet.
    case offerAddress(URL, ClipboardCopy)

    public enum Reason: Equatable, Sendable {
        case ownWrite, transient, paused, ignoredApp, empty, unsupported
        /// An address on this Mac or the local network (`WebDownload.isLocal`): only the hotkey fetches it.
        case localAddress
        case skipped(RequestFactory.Skip)
    }
}

public struct ClipboardPolicy: Sendable {
    /// Pasteboard types that mark a copy as not meant to be kept (nspasteboard.org).
    public static let transientTypes: Set<String> = [
        "org.nspasteboard.TransientType", "org.nspasteboard.ConcealedType", "org.nspasteboard.AutoGeneratedType",
    ]

    public var factory: RequestFactory

    public init(factory: RequestFactory) {
        self.factory = factory
    }

    public var isPaused: Bool { EsclopSettings.pauseAutomaticOptimisations.value(in: factory.settings) }

    /// Copied text matters only when it can be the path of an image to optimise; otherwise the
    /// watcher does not read it.
    public var readsText: Bool { EsclopSettings.optimiseImagePathClipboard.value(in: factory.settings) }

    /// What copied web addresses of media do (`optimiseURLClipboard`).
    public var addresses: CopiedAddressAction { EsclopSettings.optimiseURLClipboard.value(in: factory.settings) }

    /// Copied web addresses are offered or downloaded; with "Do nothing" the watcher does not read them.
    public var readsAddresses: Bool { addresses != .ignore }

    /// `content` is only read when the cheap checks pass. `appBefore` is the app that was in front
    /// at the poll before: a copy made just before switching apps belongs to it.
    public func decide(_ copy: ClipboardCopy, appBefore: String? = nil, content: () -> ClipboardContent) -> ClipboardAction {
        if copy.types.contains(Clipboard.optimisedType.rawValue) { return .ignore(.ownWrite) }
        if !copy.types.isDisjoint(with: Self.transientTypes) { return .ignore(.transient) }
        if isPaused { return .ignore(.paused) }
        let ignoredApps = EsclopSettings.clipboardIgnoredAppBundleIds.value(in: factory.settings)
        if [copy.app, appBefore].contains(where: { $0.map(ignoredApps.contains) ?? false }) { return .ignore(.ignoredApp) }

        switch content() {
        case let .image(data, type):
            guard factory.clipboardAllows(.image) else { return .ignore(.skipped(.disabled)) }
            if let skip = factory.sizeSkip(data.count, kind: .image) { return .ignore(.skipped(skip)) }
            return .optimiseImage(data, type, copy)
        case let .files(urls):
            return files(urls, copy: copy)
        case let .path(url):
            guard MediaKind.of(url) == .image, readsText else { return .ignore(.unsupported) }
            return files([url], copy: copy)
        case .base64Image:
            // Text stays text: replacing a data URL with an image would surprise the person.
            return .ignore(.unsupported)
        case let .address(url):
            guard readsAddresses, let kind = MediaKind.of(url) else { return .ignore(.unsupported) }
            guard factory.clipboardAllows(kind) else { return .ignore(.skipped(.disabled)) }
            guard !WebDownload.isLocal(url) else { return .ignore(.localAddress) }
            return addresses == .download ? .optimiseAddress(url, copy) : .offerAddress(url, copy)
        case .empty:
            return .ignore(.empty)
        }
    }

    private func files(_ urls: [URL], copy: ClipboardCopy) -> ClipboardAction {
        var firstSkip: RequestFactory.Skip?
        var eligible: [URL] = []
        for url in urls {
            if let skip = factory.automaticSkip(for: url) {
                firstSkip = firstSkip ?? skip
            } else {
                eligible.append(url)
            }
        }
        if !eligible.isEmpty { return .optimiseFiles(eligible, copied: urls, copy) }
        return .ignore(.skipped(firstSkip ?? .unsupported))
    }

    /// What is on the pasteboard (`Clipboard.read`), and when nothing else is, a copied web
    /// address of media (`address`). Without `addresses` no address is read.
    public static func read(_ pasteboard: NSPasteboard, text readsText: Bool = true, addresses: Bool = true) -> ClipboardContent {
        let content = Clipboard.read(pasteboard, text: readsText)
        guard content == .empty, addresses else { return content }
        let text = pasteboard.string(forType: .URL) ?? pasteboard.string(forType: .string)
        return text.flatMap(address).map(ClipboardContent.address) ?? .empty
    }

    /// The address `text` is when the whole of it, trimmed, is one http or https address
    /// (`WebDownload.address`) whose path names a kind L'Esclop optimises. Any other link is never
    /// fetched: a copied sign-in or one-time link must not be opened. Text that only contains an
    /// address is not one.
    public static func address(_ text: String) -> URL? {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.rangeOfCharacter(from: .whitespacesAndNewlines) == nil,
              let url = try? WebDownload.address(trimmed), MediaKind.of(url) != nil
        else { return nil }
        return url
    }
}
